-- Get Wired AutoWorx: verified 4,186-SKU catalogue import
-- Pricing enforced as cost x 1.15 VAT x 1.35 markup.
-- Existing product stock quantities are NOT overwritten.
BEGIN;

ON CONFLICT (sku) DO UPDATE SET
 name=EXCLUDED.name,
 source_category=EXCLUDED.source_category,
 source_subcategory=EXCLUDED.source_subcategory,
 cost_price=EXCLUDED.cost_price,
 advertised_price=EXCLUDED.advertised_price,
 source_guide=EXCLUDED.source_guide,
 source_page=EXCLUDED.source_page;

SELECT public.import_buyers_guides_catalog();

COMMIT;
